INSERT INTO liquidity_scenario (scenario_id, scenario_code, version_no, scenario_name, assumption_notes, receipt_delay_days, collection_haircut_bps, fx_shock_bps, one_off_multiplier_bps, status, effective_from, effective_to) VALUES ('SCN-002', 'DELAYED_RECEIPT', 1, 'Delayed receipts', 'Every receivable arrives 14 days later than its expected date (rolled to the next business day). Amounts, payables and FX are as in BASE.', 14, 0, 0, 10000, 'ACTIVE', '2026-01-01', NULL);
INSERT INTO liquidity_scenario (scenario_id, scenario_code, version_no, scenario_name, assumption_notes, receipt_delay_days, collection_haircut_bps, fx_shock_bps, one_off_multiplier_bps, status, effective_from, effective_to) VALUES ('SCN-003', 'STRESS', 1, 'Combined stress', 'Receivables arrive 21 days late and only 90% is collected; every non-base currency is worth 10% less in base currency (applied to flows and to the opening balance); large one-off payments cost 1.5 times their scheduled amount.', 21, 1000, -1000, 15000, 'ACTIVE', '2026-01-01', NULL);
